  "help.type.other": "其他",
  "help.faq.cantLogin.q": "无法访问我的账户",
  "help.faq.cantLogin.a": "请检查您是否使用了正确的邮箱和密码。如果忘记密码，请在登录页面点击“忘记密码？”如果问题仍然存在，请创建支持工单。",
  "help.faq.notReceiving.q": "我没有收到邮件",
  "help.faq.notReceiving.a": "请先检查垃圾邮件文件夹。确保您的存储空间没有满。如果问题持续，请确认发件人地址正确并创建工单。",
  "help.faq.cantSend.q": "我无法发送邮件",
  "help.faq.cantSend.a": "请检查您的互联网连接和收件人地址是否正确。确保附件不超过25MB。几分钟后再试。",
  "help.faq.forgotPassword.q": "我忘记了密码",
  "help.faq.forgotPassword.a": "在登录页面���点击“忘记密码？”并按照说明通过恢复邮箱重置密码。",
  "help.faq.accountSecurity.q": "我觉得我的账户被盗了",
  "help.faq.accountSecurity.a": "请立即更改您的密码。检查已发送邮件中是否有您未发送的消息。在设置 > 安全中启用两步验证。如有必要，请创建紧急工单。",
  "help.faq.appAccess.q": "如何在手机上访问应用？",
  "help.faq.appAccess.a": "您可以通过浏览器访问 Chatyy，网址为 chatyy.app，或在您的设备应用商店下载我们的应用。",
  "privacy.title": "隐私政策",
  "privacy.subtitle": "我们如何保护和处理您的数据",
  "privacy.lastUpdated": "最后更新：2026年3月",
  "privacy.dataCollection.title": "数据收集",
  "privacy.dataCollection.body": "我们仅收集提供邮件服务所需的信息：您的姓名、电子邮件地址和发送及接收的消息内容。我们不会出售或与第三方共享您的个人数据用于营销目的。",
  "privacy.dataUsage.title": "我们如何使用您的数据",
  "privacy.dataUsage.body": "您的数据仅用于操作和改善邮件服务，包括消息投递、垃圾邮件过滤、AI功能（在您同意的情况下）和账户安全。",
  "privacy.dataSecurity.title": "数据安全",
  "privacy.dataSecurity.body": "我们对所有传输和静态数据使用行业标准加密（TLS/SSL）。会话通过加密令牌和CSRF保护进行保护。我们定期审计安全实践。",
  "privacy.cookies.title": "Cookies和本地存储",
  "privacy.cookies.body": "我们使用必要的Cookies和本地存储来保持您的会话，记住您的偏好（主题、语言）并提供流畅的体验。我们不使用第三方跟踪Cookies。",
  "privacy.thirdParties.title": "第三方服务",
  "privacy.thirdParties.body": "我们可能使用第三方服务提供特定功能，如AI（Anthropic Claude）和推送通知。这些服务遵循各自的隐私政策，仅处理所需的最少数据。",
  "privacy.rights.title": "您的权利",
  "privacy.rights.body": "您有权随时访问、修正、导出或删除您的个人数据。您可以在设置中管理您的数据或联系支持。",
  "privacy.contact.title": "联系我们",
  "privacy.contact.body": "有关隐私问题或数据请求，请通过privacy@chatyy.app与我们联系。我们将在30天内回复。",
  "terms.title": "服务条款",
  "terms.subtitle": "Chatyy使用指南",
  "terms.lastUpdated": "最后更新：2026年3月",
  "terms.acceptance.title": "接受条款",
  "terms.acceptance.body": "访问或使用Chatyy即表示您同意这些服务条款。如果您不同意这些条款的任何部分，请不要使用该服务。",
  "terms.services.title": "服务描述",
  "terms.services.body": "Chatyy提供电子邮件通信服务，包括发送、接收和管理电子邮件，以及AI功能、日历集成和视频会议。",
  "terms.accounts.title": "用户账户",
  "terms.accounts.body": "您有责任保持您的凭据安全。请勿分享您的密码或允许未经授权访问您的账户。您必须至少13岁才能使用此服务。",
  "terms.conduct.title": "可接受使用",
  "terms.conduct.body": "您同意不使用该服务发送垃圾邮件、恶意软件、网络钓鱼或任何非法内容。请勿尝试访问其他用户的账户或干扰服务基础设施。",
  "terms.content.title": "内容所有权",
  "terms.content.body": "您保留通过服务创建和发送的所有内容的所有权。我们不主张对您的电子邮件或附件的所有权。我们可能会根据需要处理内容以提供服务。",
  "terms.limitation.title": "责任限制",
  "terms.limitation.body": "Chatyy按“现状”提供。我们追求99.9%的可用性，但不保证服务不间断。我们不对因使用该服务而导致的间接、附带或后果性损害负责。",
  "terms.termination.title": "账户终止",
  "terms.termination.body": "我们可以暂停或终止违反这些条款的账户。您可以随时在设置中删除您的账户。账户终止后，您的数据将在30天内删除。",
  "terms.changes.title": "条款变更",
  "terms.changes.body": "我们可能会定期更新这些条款。我们会通过电子邮件或应用内通知告知重大变更。变更后继续使用即���示接受更新的条款���",
