  // [2026-10-13 consent-lgpd] Termos/Política v2026-10-13 + Personalização e ofertas (en — sem tradução própria)
  "legal.version": "Version",
  "privacy.personalization.title": "个性化与推荐",
  "privacy.personalization.body": "为了推荐 Reels 和其他内容，Chatyy 会使用你在应用内的活动：观看的视频、观看时长、点赞、分享、收藏的内容、你点按“不感兴趣”的情况以及你选择的兴趣。\n\n法律依据：正当利益（巴西 LGPD 第 7 条第 IX 款），用于向你展示相关的推荐内容。你可以随时在“设置 > 隐私与安全 > 个性化与优惠 > 个性化推荐”中提出反对。关闭后，推荐流将显示热门和最新内容，你的活动将不再用于推荐。\n\n我们不会读取你的聊天、电子邮件、文件或通话来推荐内容。只有在你给予“可选同意”中所述的特定同意时，才会这样做。\n\n保留期限：用于推荐的活动信号最多保留 12 个月，之后将被删除或匿名化。如果你关闭个性化或删除账号，这些数据将不再被使用，并在 30 天内删除。我们不会出售这些数据，也不会将其分享给广告商。",
  "privacy.optionalConsents.title": "可选同意",
  "privacy.optionalConsents.body": "有两个选项需要你的特定同意（LGPD 第 7 条第 I 款及第 8 条）。它们默认关闭，彼此独立，不是使用 Chatyy 的前提条件，并且可以随时在“设置 > 隐私与安全 > 个性化与优惠”中免费撤回。\n\n1. 使用我聊天和电子邮件中的兴趣来个性化推荐。如果你开启此项，你的设备会识别聊天和电子邮件中的一般话题（例如“足球”或“烹饪”）。分析在设备本地进行：不会将任何聊天或电子邮件文本发送到我们的服务器；只有得出的话题可能被用于调整推荐。此功能尚未启用；启用后，仅对开启了此项的用户生效。\n\n2. 接收 Chatyy 及合作伙伴的优惠和促销信息。如果你开启此项，我们可能会通过通知、电子邮件和应用内消息向你发送优惠。发送由我们完成：我们不会与合作伙伴分享你的数据。每封促销电子邮件都包含退订链接。\n\n记录：我们会保存每次同意和每次撤回的日期和时间、文本版本、给出同意的位置（注册、通知或设置）、平台以及部分 IP 地址，以证明你的选择。这些记录在账号存续期间及之后最多 5 年内保存，仅作为证明及维护权利之用；这是“数据保留与删除”的例外情况。撤回同意不影响撤回之前已进行的处理。",
  "privacy.titularRights.title": "你的权利（LGPD 第 18 条）",
  "privacy.titularRights.body": "你可以随时免费：确认我们是否处理你的数据；访问你的数据；更正不完整、不准确或过时的数据；要求对不必要、过度或非法处理的数据进行匿名化、封锁或删除；要求数据可携带；要求删除基于同意处理的数据；了解我们与谁共享数据；获知你可以拒绝同意及其后果；撤回同意；以及反对基于正当利益的处理，例如个性化。你还可以要求复核完全由自动化处理做出的决定（第 20 条），并向巴西国家数据保护局（ANPD）投诉。如需行使这些权利，请使用应用设置，或写信给我们的数据保护官（见“数据保护官及联系方式”）。",
  "privacy.transparency.title": "Transparency",
  "privacy.transparency.body": "Chatyy 使用开放的标准技术，例如用于电子邮件的 IMAP/SMTP 和用于通话的 WebRTC。我们不使用隐藏算法对你的消息和电子邮件进行排序或过滤。我们对推荐算法的使用已在“个性化与推荐”中说明，并且可以关闭。我们不会出售你的数据，也不会将其分享给广告商或合作伙伴。你可以写信至 privacy@chatyy.app，询问任何功能如何处理你的数据。",
  "privacy.dpo.title": "数据保护官及联系方式",
  "privacy.dpo.body": "数据保护官（DPO）：privacy@chatyy.app。我们会在 15 天内回复。有关个性化和优惠的选择，也可以随时在“设置 > 隐私与安全 > 个性化与优惠”中进行。",
  "terms.recommendations.title": "推荐与优惠",
  "terms.recommendations.body": "使用 Chatyy 即表示你知悉：我们会根据你在应用内的活动推荐 Reels 和其他内容，具体如隐私政策（“个性化与推荐”）所述。你可以随时在“设置 > 隐私与安全 > 个性化与优惠”中关闭个性化推荐；关闭后，推荐流将显示热门和最新内容。\n\n只有在你开启相应选项后，我们才会发送 Chatyy 及合作伙伴的优惠和促销信息。该选项独立于本条款，默认关闭，你可以随时关闭。将你聊天和电子邮件中的兴趣用于推荐同样需要单独同意。接受本条款不包括上述任何同意，拒绝这些同意也不会限制你使用 Chatyy。",
  "terms.privacyConsent.title": "Privacy",
  "terms.privacyConsent.body": "我们如何处理你的个人数据已在隐私政策中说明，隐私政策是本条款的一部分。我们使用你的数据来提供你注册的服务（电子邮件、聊天、通话、云盘及其他功能）、履行法律义务、基于正当利益（例如安全和推荐，你有权反对），以及在必要时基于你的特定同意，该同意始终是可选的，并可随时撤回。我们仅使用运行服务所必需的服务提供商（例如用于通知和 AI），具体如政策所述。",
  "consents.title": "个性化与优惠",
  "consents.intro": "选择 Chatyy 如何个性化你看到的内容，以及你是否希望接收优惠。此处所有选项都不是使用应用的必要条件。",
  "consents.sectionRecommendations": "Recommendations",
  "consents.personalizedTitle": "个性化推荐",
  "consents.personalizedDesc": "我们会根据你在 Chatyy 上的行为（观看的视频、观看时长、点赞、分享、收藏和“不感兴趣”）来推荐 Reels。",
  "consents.personalizedFooter": "关闭后，推荐流将显示热门和最新内容。我们绝不会为此读取你的聊天或电子邮件。",
  "consents.sectionOptional": "Optional",
  "consents.chatInterestsTitle": "使用我聊天和电子邮件中的兴趣来个性化推荐",
  "consents.chatInterestsDesc": "话题在你的设备上识别；不会发送任何聊天或电子邮件文本。此功能仍在准备中：目前我们只保存你的选择。",
  "consents.chatInterestsShort": "话题在你的设备上识别；不会发送任何文本。",
  "consents.marketingTitle": "接收 Chatyy 及合作伙伴的优惠和促销信息",
  "consents.marketingDesc": "通过通知、电子邮件和应用内消息发送。我们不会与合作伙伴分享你的数据。可随时在此处或通过每封电子邮件中的链接取消。",
  "consents.marketingShort": "通过通知、电子邮件和应用内消息发送。可随时取消。",
  "consents.learnMore": "了解详情",
  "consents.optionalHint": "可选。你可以随时在“设置 > 隐私与安全 > 个性化与优惠”中更改。",
  "consents.recordNote": "我们会保存每次选择的记录（日期、文本版本和选择位置）作为证明。如有疑问：privacy@chatyy.app",
  "consents.saveFailed": "暂时无法将你的选择保存到服务器。我们会自动重试。",
  "consents.sectionDocs": "Documents",
  "consents.signupTitle": "更多选项（可选）",
  "consents.updateTitle": "我们更新了条款和隐私政策",
  "consents.updateIntro": "变更摘要：",
  "consents.updatePoint1": "我们说明了如何根据你在 Chatyy 上的行为推荐 Reels 和其他内容，以及如何关闭推荐。",
  "consents.updatePoint2": "我们新增了两个独立选项，均默认关闭：使用你聊天和电子邮件中的兴趣（在你的设备上分析），以及接收优惠和促销信息。",
